from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
APP = ROOT / "tools/climate_analyzer/app.py"
CHARTS = ROOT / "tools/climate_analyzer/epw_climate_analyzer/charts.py"
TEST = ROOT / "tools/climate_analyzer/tests/test_climate_0_10_4_regressions.py"

app = APP.read_text(encoding="utf-8")
old = '''def render_comparison_basket_manager(active_file: ClimateFilePayload | None) -> None:\n    """Render controls for adding, renaming and removing comparison climates."""\n    st.subheader("Comparison basket")\n'''
new = '''def render_comparison_basket_manager(active_file: ClimateFilePayload | None) -> None:\n    """Render controls for adding, renaming and removing comparison climates."""\n    # Compare Climates must not depend on the Find climate map dependency gate.\n    # Keep all catalog/download helpers page-local so direct navigation to this\n    # page is safe in a fresh Streamlit process.\n    from epw_climate_analyzer.catalog_runtime import catalog_runtime_summary, station_provenance_text\n    from epw_climate_analyzer.climate_sources import download_station_epw, filter_station_catalog\n\n    st.subheader("Comparison basket")\n'''
if old not in app:
    raise SystemExit("comparison basket anchor not found")
app = app.replace(old, new, 1)
APP.write_text(app, encoding="utf-8")

charts = CHARTS.read_text(encoding="utf-8")
old_cb = 'colorbar=dict(title=color_metric_label, orientation="h", x=0.5, y=-0.08, len=0.42, thickness=10)'
new_cb = 'colorbar=dict(title=color_metric_label, orientation="h", x=0.36, y=-0.20, len=0.44, thickness=12, xanchor="center", yanchor="top")'
count = charts.count(old_cb)
if count != 2:
    raise SystemExit(f"expected 2 psychrometric colorbars, found {count}")
charts = charts.replace(old_cb, new_cb)

old_layout = '''    fig.update_layout(\n        height=900,\n        autosize=True,\n        hovermode="closest",\n        legend=dict(\n            title=dict(text="Month", font=dict(size=13)),\n            orientation="h",\n            yanchor="top",\n            y=-0.12,\n            xanchor="left",\n            x=0.0,\n            itemsizing="constant",\n            font=dict(size=12),\n            groupclick="toggleitem",\n            traceorder="normal",\n        ),\n        legend2=dict(\n            title=dict(text="Zones", font=dict(size=13)),\n            orientation="h",\n            yanchor="top",\n            y=-0.28,\n            xanchor="left",\n            x=0.0,\n            itemsizing="constant",\n            font=dict(size=12),\n            groupclick="togglegroup",\n            traceorder="normal",\n        ),\n        margin=dict(l=64, r=44, t=74, b=340),\n    )\n'''
new_layout = '''    fig.update_layout(\n        height=760,\n        autosize=True,\n        hovermode="closest",\n        legend=dict(\n            title=dict(text="Month", font=dict(size=13)),\n            orientation="h",\n            yanchor="top",\n            y=-0.12,\n            xanchor="center",\n            x=0.36,\n            itemsizing="constant",\n            font=dict(size=12),\n            groupclick="toggleitem",\n            traceorder="normal",\n        ),\n        legend2=dict(\n            title=dict(text="Zones", font=dict(size=13)),\n            orientation="v",\n            yanchor="top",\n            y=1.0,\n            xanchor="left",\n            x=0.755,\n            itemsizing="constant",\n            font=dict(size=12),\n            groupclick="togglegroup",\n            traceorder="normal",\n        ),\n        margin=dict(l=64, r=24, t=74, b=155),\n    )\n    # Explicitly allocate the responsive figure width between the chart and the\n    # zone legend.  This avoids Plotly shrinking the plotting domain to the old\n    # near-square area while still using the full Streamlit container.\n    fig.update_xaxes(domain=[0.0, 0.72])\n'''
if old_layout not in charts:
    raise SystemExit("psychrometric layout anchor not found")
charts = charts.replace(old_layout, new_layout, 1)
CHARTS.write_text(charts, encoding="utf-8")

TEST.write_text('''import ast\nimport unittest\nfrom pathlib import Path\n\nimport pandas as pd\n\nfrom epw_climate_analyzer.charts import psychrometric_chart\n\n\nROOT = Path(__file__).resolve().parents[1]\n\n\nclass Climate0104RegressionTests(unittest.TestCase):\n    def test_compare_catalog_helpers_are_page_local(self):\n        source = (ROOT / "app.py").read_text(encoding="utf-8")\n        tree = ast.parse(source)\n        fn = next(node for node in tree.body if isinstance(node, ast.FunctionDef) and node.name == "render_comparison_basket_manager")\n        imported = set()\n        for node in ast.walk(fn):\n            if isinstance(node, ast.ImportFrom):\n                imported.update(alias.name for alias in node.names)\n        self.assertTrue({"catalog_runtime_summary", "station_provenance_text", "download_station_epw", "filter_station_catalog"}.issubset(imported))\n\n    def _frame(self):\n        rows = []\n        for month in range(1, 13):\n            rows.append({\n                "dry_bulb_temperature_c": float(month + 5),\n                "relative_humidity_pct": 40.0 + month,\n                "humidity_ratio_g_kg": 4.0 + month * 0.25,\n                "moist_air_enthalpy_kj_kg": 20.0 + month,\n                "month_index": month,\n                "month_name": str(month),\n                "hour_of_day": 12,\n            })\n        return pd.DataFrame(rows)\n\n    def test_psychrometric_domain_uses_page_width_with_zones_at_right(self):\n        fig = psychrometric_chart(\n            self._frame(),\n            chart_type="T-d",\n            show_comfort_zone=True,\n            shown_bioclimatic_zones=["Comfort zone", "Permissible comfort zone"],\n            color_mode="Month",\n        )\n        self.assertTrue(fig.layout.autosize)\n        self.assertIsNone(fig.layout.width)\n        self.assertEqual(list(fig.layout.xaxis.domain), [0.0, 0.72])\n        self.assertEqual(fig.layout.legend.orientation, "h")\n        self.assertAlmostEqual(fig.layout.legend.x, 0.36)\n        self.assertEqual(fig.layout.legend2.orientation, "v")\n        self.assertGreaterEqual(fig.layout.legend2.x, 0.75)\n        zone_traces = [trace for trace in fig.data if getattr(trace, "legend", None) == "legend2" and getattr(trace, "showlegend", False)]\n        self.assertEqual([trace.legendrank for trace in zone_traces], [1, 2])\n\n    def test_frequency_colorbar_is_below_axis_labels(self):\n        fig = psychrometric_chart(\n            self._frame(),\n            chart_type="T-d",\n            show_comfort_zone=False,\n            data_mode="Distributive grid",\n            color_mode="Frequency",\n            color_metric_label="Frequency [h]",\n        )\n        bars = []\n        for trace in fig.data:\n            marker = getattr(trace, "marker", None)\n            colorbar = getattr(marker, "colorbar", None) if marker is not None else None\n            if colorbar is not None and getattr(marker, "showscale", False):\n                bars.append(colorbar)\n        self.assertEqual(len(bars), 1)\n        self.assertLessEqual(bars[0].y, -0.18)\n        self.assertAlmostEqual(bars[0].x, 0.36)\n\n\nif __name__ == "__main__":\n    unittest.main()\n''', encoding="utf-8")
print("CLIMATE-0.10.4 remediation applied")
